insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('catback-r32','bub','catback-r32','Cat-back exhaust (R32)','Engine','exhaust',array['exhaust','cat back','catback','milltek','borla','tampa mod','flapper']::text[],true,'3–4 hr',2) on conflict (id) do update set title=excluded.title, aliases=excluded.aliases, live=true, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('headers-r32','bub','headers-r32','Headers & high-flow cat pipes (R32)','Engine','exhaust',array['headers','manifolds','downpipe','test pipe','high flow cat']::text[],true,'1–2 days',4) on conflict (id) do update set title=excluded.title, aliases=excluded.aliases, live=true, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('turbo-kit-r32','bub','turbo-kit-r32','Turbo kit (complete systems)','Forced induction',null,array['turbo','turbo kit','hpa','034','jdy','boost','forced induction','supercharger']::text[],true,'3–5 days',5) on conflict (id) do update set title=excluded.title, category=excluded.category, aliases=excluded.aliases, live=true, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('catback-r32',$j${"id": "catback-r32", "title": "Cat-back exhaust (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-exhaust-hero", "alsoFits": "Mk5 R32 only; Mk4 R32 and Golf R systems differ", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which cat-back?", "hint": "All of them use the single 60mm sleeve joint ahead of the cross brace. They differ in volume and in what happens to the stock muffler's vacuum flapper.", "options": [{"id": "resonated", "label": "Resonated (civil)", "when": "Milltek resonated, Borla. Daily-driver volume."}, {"id": "nonres", "label": "Non-resonated (loud)", "when": "Milltek non-res, Magnaflow non-res. You'll be heard."}, {"id": "valved", "label": "Valved (ECS, remote)", "when": "Keeps a muffler valve on a remote; the install PDF this guide follows."}, {"id": "tampa", "label": "Resonator delete ('Tampa mod')", "when": "Cut and weld at a muffler shop. Budget."}]}, "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 2, "cost": "$700–1,800 · $100–200 for the Tampa mod", "risk": "Hot parts · a seized sleeve clamp · the propshaft runs right there", "why": "A cat-back swaps the mid-pipe and muffler behind the R32's cats. It's where the VR6 sound lives, it drops weight off the back, and it's a single afternoon with a clamp and some hangers. It doesn't add power on a naturally aspirated six, and it's the classic first R32 mod anyway.", "note": "ECS's Mk5 R32 cat-back PDF is the reference for the stock system; the exhaust megathread covers what owners run and why."}, "heroCap": "Underneath: the stock downpipe with the cats ahead of the cross brace, a single 60mm sleeve joint into the cat-back, mid-pipe running beside the propshaft, centre-exit muffler with the vacuum flapper.", "lifespan": {"title": "When owners do this", "headline": ["Cat-back: the classic first R32 mod. Pipes ahead of the cats rot by 150k on salt-belt cars."], "earliest": null, "detail": "Nothing forces the cat-back; it's sound. High-mileage cars do rust through the downpipe section ahead of the cats, so an exhaust job sometimes starts as a repair.", "factors": ["Want the noise", "Rust belt", "Cams and a tune (headers)"], "inspect": ["Look at the pipes ahead of the cats when the car's up for anything else"], "confidence": {"level": "community", "n": 3, "note": "Owner threads."}}, "should": {"yesIf": ["Want the VR6 to be heard", "Rusted mid-pipe or muffler", "Weight off the back"], "codes": [], "notes": ["The flapper: the stock muffler valve is vacuum-actuated and normally closed, opening with revs for volume. Some cat-backs keep a valve (ECS's is remote-controlled), most delete it. If you keep the factory muffler and want it open all the time, unplugging and capping the vacuum line leaves it closed, not open; owners wire a switch instead.", {"text": "Sleeve clamp joint: the cat-back meets the stock downpipe at a single 60mm sleeve clamp ahead of the cross brace. Every cat-back uses that joint; no cutting."}, {"text": "The Tampa mod is a resonator delete done at a muffler shop: cut the stock resonator out and weld in straight pipe or a larger free-flow resonator. Owners love the sound per dollar; it's loud and a little raspy. Bring the shop the thread so they know what you mean.", "only": ["tampa"]}], "confidence": {"level": "medium", "n": 3, "note": "ECS PDF for the stock system; owner megathread for options and results."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back system", "pn": "see options below", "note": "Mid-pipe, muffler, tips, sleeve clamp; hangers transfer from stock", "price": "$700–1,800", "links": [], "only": ["resonated", "nonres", "valved"]}, {"tier": "aftermarket", "name": "Muffler-shop labour + pipe or resonator", "pn": "—", "note": "", "price": "$100–200", "links": [], "only": ["tampa"]}, {"tier": "oe", "name": "Exhaust hangers (×4), cross-brace nuts", "pn": "—", "note": "Hangers tear; replace", "price": "$40", "links": []}], "aftermarket": [{"name": "Milltek cat-back (resonated / non-resonated)", "note": "The reference R32 system. Resonated is civil; non-res is loud.", "price": "$1,200–1,800", "signal": "Forum favorite", "links": []}, {"name": "Borla cat-back", "note": "Deep and quiet cruising, loud on throttle; owners praise the tone.", "price": "$900–1,200", "signal": "Best daily tone", "links": []}, {"name": "Magnaflow cat-back", "note": "Value; non-resonated attracts attention, per owners.", "price": "$700–900", "signal": "Value", "links": []}, {"name": "ECS valved cat-back", "note": "Keeps a muffler valve with a remote. The PDF this guide follows.", "price": "$1,000–1,300", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_14107_VW_MK5_R32_Exhaust_System_Installation_r1.pdf"}]}, {"name": "'Tampa mod' resonator delete", "note": "Budget: cut the resonator, weld in a straight pipe or a bigger resonator. Owners love the sound per dollar.", "price": "$100–200 at a shop", "signal": "Budget", "links": []}], "tools": [{"name": "13mm and 15mm sockets, ratchet, breaker bar; exhaust hanger pliers"}, {"name": "Jack, four stands; penetrating oil; ball-pein hammer for slip joints"}], "before": ["Exhaust cold.", "Soak the sleeve clamp and any flange nuts the night before.", "Lay the new system out and test-fit every slip joint on the floor (ECS: tap them round with a hammer if they don't slide)."], "steps": [{"n": 1, "title": "Raise the car, support the exhaust", "blocks": [{"t": "text", "b": "Four stands. Support the system from below (a jack with a board). Remove the four 13mm nuts holding the chassis cross brace and set the brace aside."}]}, {"n": 2, "title": "Stock cat-back off", "blocks": [{"t": "text", "b": "Loosen the sleeve clamp between the downpipe and the cat-back and slide it forward onto the downpipe. Disconnect the vacuum line from the muffler valve. Pop the two front hangers with the pliers. Unbolt the muffler hangers from the body. Lower the whole system and slide it out."}, {"t": "ill", "id": "r32-exhaust-hero", "cap": "One sleeve joint ahead of the brace, two front hangers, bolted muffler hangers, and the flapper's vacuum line."}]}, {"n": 3, "title": "Tampa mod: to the shop", "only": ["tampa"], "blocks": [{"t": "text", "b": "With the system out (or on the car, if the shop prefers), the resonator section is cut out and straight pipe or a larger resonator is welded in. Ask for the hangers to stay where they were. Skip to the refit."}]}, {"n": 3, "title": "New system in, loose", "only": ["resonated", "nonres", "valved"], "blocks": [{"t": "text", "b": "Transfer the stock hangers to the new mid-pipe and muffler in the same orientation. Extension/mid-pipe into the downpipe with the sleeve clamp, then the muffler, then the tips: all snug, nothing torqued, no impact gun."}, {"t": "text", "b": "Valved: mount the solenoid and control module (ECS used a stud on the driver's strut tower and the underside of the fuse box), tee the short hose into the vacuum line at the check valve ahead of the reservoir under the intake manifold, run the long hose down past the subframe to the muffler, power from an ignition-live fuse with an add-a-circuit.", "only": ["valved"]}]}, {"n": 4, "title": "Clearance, hangers, tips", "caution": true, "blocks": [{"t": "text", "b": "Walk the system: clearance to the propshaft, the subframe and the trunk floor at the mid-pipe; to the heat shields and the cross brace at the front. Hangers level side to side and pitched so the lower hole sits 10–15 mm forward of the upper (they swing back as it heats). Centre the tips in the valance cut-outs and set their depth."}, {"t": "warn", "b": "The propshaft is what a GTI doesn't have. A mid-pipe that kisses it shows up as a vibration at speed and a polished line on the pipe. Check it with the car on the ground too."}]}, {"n": 5, "title": "Tighten front to back", "blocks": [{"t": "text", "b": "Push each joint upward as you tighten its clamp, front to back. Let it settle; re-walk the clearances. Vacuum line to the muffler valve if the new system has one. Cross brace back on (13mm), belly pans."}]}, {"n": 6, "title": "Start, drive, re-check", "blocks": [{"t": "text", "b": "Start it and listen for leaks at the joints. Drive; a new rattle over bumps is a hanger or a heat shield. Re-check every clamp at 500 miles (ECS)."}]}], "alsoReplace": [{"name": "Exhaust hangers", "why": "Rubber, twenty years old, and you have pliers in your hand."}, {"name": "Cross-brace nuts", "why": "Rusty; new ones now."}, {"name": "Look at the pipes ahead of the cats", "why": "High-mileage R32s rot the section before the cats. If yours is thin, the headers guide covers replacing that section."}], "check": {"tab": "How loud?", "title": "How loud do you want it?", "illId": "r32-exhaust-hero", "illCap": "Volume goes up; neighbours' patience goes down.", "rows": [{"see": "Daily driver, want the VR6 note", "means": "Resonated.", "do": "Milltek resonated or Borla."}, {"see": "Weekend car, want to be heard", "means": "Non-resonated.", "do": "Milltek non-res or Magnaflow non-res."}, {"see": "Want it quiet at 7am and loud at 7pm", "means": "Valved.", "do": "ECS valved with the remote."}, {"see": "Budget", "means": "Resonator delete.", "do": "Tampa mod at a muffler shop."}], "c": {"level": "community", "n": 3, "note": "Exhaust megathread."}}, "aftercare": ["Clamps at 500 miles.", "Look at the mid-pipe's propshaft clearance after the first hot drive."], "disagreements": [{"topic": "Power from a cat-back?", "pos": "Vendors imply gains.", "call": "None worth measuring on an NA VR6. It's sound and weight."}, {"topic": "Flapper", "pos": "Delete it, keep it, switch it.", "call": "Most cat-backs delete it. If you keep the stock muffler, wire a switch; capping the vacuum leaves it closed."}], "sources": ["ECS Tuning 'MK5 R32 Valved Exhaust System Installation' PDF (stock system removal, clearances, hangers)", "VWVortex 'Official MkV R32 Exhaust Thread' and 'exhaust system for mk5 r32'", "Milltek, Borla, Magnaflow, USP listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('headers-r32',$j${"id": "headers-r32", "title": "Headers & high-flow cat pipes (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-exhaust-hero", "alsoFits": "Mk5 R32 only; Mk4 R32 and Golf R systems differ", "category": "Engine", "kind": "upgrade", "variants": {"question": "How far?", "hint": "Headers replace the two cast manifolds; the pipes that connect them to the cat-back can keep high-flow cats or run catless.", "options": [{"id": "catted", "label": "Headers + high-flow catted pipes", "when": "The street version. Codes are manageable with a tune."}, {"id": "catless", "label": "Headers + test pipes", "when": "Off-road only. Loud, and the ECU will complain without a tune."}]}, "glance": {"timeFirst": "a full day, often two", "timeRepeat": "6 hr", "difficulty": 4, "cost": "$1,500–2,500 headers · $500–1,200 pipes", "risk": "Rear manifold against the firewall · snapped studs · emissions", "why": "Headers are the one exhaust part that makes real power on a naturally aspirated VR6, and only when paired with cams and a tune. The rear manifold sits against the firewall and comes out blind, which is why owners call this a day by itself. If you're going forced induction instead, stop: the turbo kit brings its own manifold and this guide doesn't apply.", "note": "Owner reports from the R32 exhaust megathread; there is no complete public install sheet for R32 headers, so the steps are at the level owners describe."}, "heroCap": "Twin cast manifolds at the front and back of the VR6 into the downpipe with its cats. Headers replace the manifolds; the connecting pipes decide whether the cats stay.", "lifespan": {"title": "When owners do this", "headline": ["With cams and a tune, or when the pipes ahead of the cats have rotted through"], "earliest": null, "detail": "On a stock engine the gain from headers is small and expensive. With Schrick 268/264 cams and a tune it's the combination owners on the megathread run. High-mileage salt-belt cars sometimes get here by necessity: the section ahead of the cats rusts.", "factors": ["Cams and a tune", "Rusted downpipe section", "Track use"], "inspect": ["Pipes ahead of the cats whenever the car's up"], "confidence": {"level": "community", "n": 3, "note": "Exhaust megathread."}}, "should": {"yesIf": ["Cams and a tune on the way or done", "Rotted pipes ahead of the cats", "You're staying naturally aspirated and want the last few horsepower"], "codes": [], "notes": [{"text": "High-flow cats keep the car closer to legal and keep the smell down. Expect P0420/P0430 to need a tune's attention anyway.", "only": ["catted"]}, {"text": "Test pipes remove the emissions equipment: not street-legal in most of the US, and the ECU throws P0420/P0430 without a tune or spacers. Know what you're buying.", "only": ["catless"]}, "Turbo owners: skip this. Every complete turbo kit for the R32 brings its own manifold and downpipe (see the turbo kit guide)."], "confidence": {"level": "medium", "n": 3, "note": "Owner reports; no manufacturer procedure available for R32 headers."}}, "parts": [{"tier": "aftermarket", "name": "Headers (pair)", "pn": "Milltek manifolds; others by quote", "note": "", "price": "$1,500–2,500", "links": []}, {"tier": "aftermarket", "name": "Connecting pipes with high-flow cats", "pn": "USP catted, Scorpion, Milltek", "note": "", "price": "$800–1,200", "links": [], "only": ["catted"]}, {"tier": "aftermarket", "name": "Test pipes", "pn": "USP race pipe", "note": "Off-road", "price": "$500–800", "links": [], "only": ["catless"]}, {"tier": "oe", "name": "Manifold gaskets, new manifold nuts/studs, flange gaskets, O2 sensor anti-seize", "pn": "—", "note": "Buy a stud kit before you start", "price": "$80", "links": []}], "aftermarket": [{"name": "Milltek manifolds + downpipes", "note": "The megathread's reference header set; sold with matching downpipes.", "price": "$2,000–3,000", "signal": "Reference set", "links": []}, {"name": "USP downpipes / race pipe", "note": "The pipes-only upgrade of choice: catted and catless versions for the stock manifolds or headers.", "price": "$600–1,000", "signal": "Pipes pick", "links": []}, {"name": "Scorpion downpipes with high-flow cats", "note": "Owner-reported alternative on the megathread.", "price": "$700–1,000", "signal": "Alternative", "links": []}], "tools": [{"name": "13, 15, 16mm sockets and wrenches; triple-square bits for flange hardware; long extensions and a wobble; O2 sensor socket"}, {"name": "Torch or induction heater, penetrating oil, stud extractor and thread chaser; new studs on hand"}, {"name": "Jack, four stands; a mirror and a light for the rear bank"}], "before": ["Exhaust cold. Soak every manifold nut and flange nut the night before.", "Order a stud kit and gaskets before you start; a snapped stud with no spare ends the day.", "Read the cat-back guide first: the whole system behind the cats comes out for this."], "steps": [{"n": 1, "title": "Cat-back out", "blocks": [{"t": "text", "b": "Cross brace (4× 13mm), sleeve clamp, flapper vacuum line, hangers, muffler hangers, and the cat-back is out (cat-back guide, steps 1–2)."}, {"t": "ill", "id": "r32-exhaust-hero", "cap": "Everything behind the cats comes out first."}]}, {"n": 2, "title": "Downpipe section off", "caution": true, "blocks": [{"t": "text", "b": "Unplug the O2 sensors (label which is which). Flange nuts at both manifolds (soak, heat if needed), any bracket to the transmission, and work the downpipe assembly out past the subframe. Transfer the O2 sensors to the new pipes with anti-seize on the threads."}, {"t": "warn", "b": "Manifold studs snap. Heat, oil, patience, and a stud kit on the shelf before you start."}]}, {"n": 3, "title": "Front manifold off", "blocks": [{"t": "text", "b": "Heat shield off. Manifold nuts from the front; the front bank is the easy one. Manifold off, gasket face cleaned."}]}, {"n": 4, "title": "Rear manifold off", "caution": true, "blocks": [{"t": "text", "b": "The rear manifold sits against the firewall. Heat shield out from below. Nuts come off from below and behind with extensions, a wobble and a mirror; some owners drop the rear of the engine slightly on the mounts for room. Manifold out downward."}, {"t": "warn", "b": "Reached blind. Label the sockets that fit before you're under there, and don't round a nut you can't see."}]}, {"n": 5, "title": "Headers in", "blocks": [{"t": "text", "b": "New gaskets, headers on with new nuts in a criss-cross, rear first while you still have room. Heat shields per the header maker (often modified or deleted)."}, {"t": "torque", "label": "Manifold nuts (M8)", "nm": 25, "c": {"level": "single", "n": 1, "note": "25 Nm is the usual VW M8 exhaust-manifold value; no header-maker figure confirmed. Flagged."}}]}, {"n": 6, "title": "Pipes to the headers", "blocks": [{"t": "text", "b": "Connecting pipes to the header flanges with new gaskets, O2 sensors in, pipes routed clear of the subframe and the propshaft.", "only": ["catted", "catless"]}]}, {"n": 7, "title": "Cat-back back on, tighten, drive", "blocks": [{"t": "text", "b": "Cat-back in per its guide (loose, clearances, hangers, tighten front to back). Start it and check every flange for leaks (a ticking exhaust leak at the manifold is a gasket). Tune before you drive it hard; re-torque the manifold nuts after the first heat cycle."}]}], "alsoReplace": [{"name": "O2 sensors", "why": "If original, new ones now save a second flange fight."}, {"name": "Cams and a tune", "why": "Headers without them is expense without result."}, {"name": "Motor mounts", "why": "If you dropped the engine for the rear manifold, look at them."}], "check": {"tab": "Worth it?", "title": "Are headers worth it on your car?", "illId": "r32-exhaust-hero", "illCap": "Depends entirely on what else is done.", "rows": [{"see": "Stock engine, want sound", "means": "Wrong part.", "do": "Cat-back."}, {"see": "Cams + tune, staying NA", "means": "This is the combination.", "do": "Headers + catted pipes."}, {"see": "Thinking about a turbo", "means": "Kit brings its own manifold.", "do": "Turbo kit guide; skip this."}], "c": {"level": "community", "n": 3, "note": "Megathread."}}, "aftercare": ["Re-torque manifold nuts after the first heat cycle.", "Watch for exhaust smell in the cabin: a rear-manifold leak sits right under the cowl."], "disagreements": [{"topic": "Gain on a stock engine?", "pos": "Vendors: 15–20 hp. Owners: hard to feel.", "call": "Do it with cams or not at all."}, {"topic": "Drop the engine for the rear bank?", "pos": "Some do, some don't.", "call": "If your hands don't fit, drop it an inch on the mounts rather than round a nut."}], "sources": ["VWVortex 'Official MkV R32 Exhaust Thread' (owner setups: Milltek manifolds, Scorpion/USP pipes, Schrick cams)", "ECS Mk5 R32 exhaust PDF (cat-back removal)", "Milltek, USP, Scorpion listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('turbo-kit-r32',$j${"id": "turbo-kit-r32", "title": "Turbo kit (complete systems)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "turbo-kit-hero", "alsoFits": "HPA and 034 also sell versions for the Mk4 R32, Audi A3 8P 3.2 and TT 3.2; hardware differs by chassis", "category": "Forced induction", "kind": "upgrade", "variants": {"question": "Which kit are you planning around?", "hint": "Complete systems only: turbo, manifold, downpipe, plumbing, fuelling and software in one box. Piecemeal builds are a different conversation.", "options": [{"id": "dtm", "label": "HPA DTM (EFR 7670, ~7 psi)", "when": "Entry tier. 340 hp on a Mk5 with stock fuelling. The turbo that doesn't feel like a turbo."}, {"id": "ft", "label": "HPA FT-410 / FT-470 (EFR 7670, 16–22 psi)", "when": "Adds the liquid-cooled intake manifold and bigger support parts. 410–470 hp."}, {"id": "ftx", "label": "HPA FTX (EFR 8374)", "when": "500+ hp under 20 psi. The DSG becomes the limit."}, {"id": "o34", "label": "034Motorsport Stage 1 / 2", "when": "$5,895 with software and fuelling; ~300 whp on Stage 1; Stage 2 adds the head spacer."}, {"id": "jdy", "label": "JDY Performance", "when": "Built to order by an R32 specialist; specs by quote."}]}, "glance": {"timeFirst": "3–5 days · 30–40 hr", "timeRepeat": "—", "difficulty": 5, "cost": "$6,000–14,000 kit · $2,000–6,000 in things that aren't in the box", "risk": "Compression, fuelling, heat and a DSG with a torque limit · a wrong step costs an engine", "why": "Naturally aspirated, a 3.2 VR6 makes 250 hp and sounds like the best engine VW ever built. Turbocharged, the same block makes 340 to 500+ with all-wheel drive to put it down. Complete kits from HPA and 034 exist because the VR6 turbo recipe has been worked out over twenty years: a cast manifold that keeps the O2 sensors where the DSG expects them, a compression drop, bigger injectors, software, and heat management. This guide is about choosing a kit, understanding what it does to the car, and everything you'll need that isn't in the box.", "note": "Written from HPA's published tiers and contents, 034's Stage 1 release thread and the R32 community. No complete public install PDF exists for the Mk5, so the install section is a map, not turn-by-turn."}, "heroCap": "Schematic of a single-turbo VR6: exhaust manifold → turbo → downpipe; compressed air → intercooler (air-to-water in HPA's manifold) → intake; oil and coolant lines to the turbo; bigger injectors and software to match. Not a recreation of any kit's install photos.", "lifespan": {"title": "When owners do this", "headline": ["When the car is otherwise sorted and the owner has a plan for the DSG"], "earliest": null, "detail": "Owners who turbo an R32 have usually done the maintenance first (timing chains, coolant pipe, DSG and Haldex service) because the kit puts every one of those under more stress, and because the install has the front of the engine apart anyway.", "factors": ["Maintenance state of the engine", "DSG health (clutch packs are the limit)", "Budget for the parts not in the box"], "inspect": ["Compression test and oil analysis before you spend a dollar on a kit"], "confidence": {"level": "community", "n": 3, "note": "R32 community consensus."}}, "should": {"yesIf": ["You want 340+ hp with AWD and a car that still drives to work", "The engine is healthy (compression test, no chain noise)", "You have a budget for the whole project, not the kit price"], "codes": [], "notes": ["Compression. HPA's kits all include a 4 mm compression-reduction kit (a head spacer, taking the 11.3:1 VR6 to about 7.5:1 on their spec); 034's Stage 1 runs stock compression at low boost and Stage 2 adds a spacer (8.5:1 on the Mk5). A spacer means the head comes off. That's the difference between a two-day and a four-day install and it's the single biggest decision in the project.", {"text": "DTM on a Mk5: HPA states 340 hp rather than 350 because of the stock fuelling on the Mk5. It runs about 7 psi on a stock-compression-ish setup with the spacer; owners describe it as an R32 that pulls harder everywhere rather than a boosted car.", "only": ["dtm"]}, {"text": "FT-410 and FT-470 add HPA's liquid-cooled cast intake manifold (air-to-water intercooling) and run 16–22 psi. That's where the kit stops being a bolt-on and becomes a project: chargecooler plumbing, a coolant loop and pump, and the fuel system that 470 hp asks for.", "only": ["ft"]}, {"text": "FTX (EFR 8374): 500+ hp and 500+ lb-ft under 20 psi. At this level the stock DSG clutch packs are the limit; budget a TCU tune and clutch pack work, or don't buy this tier.", "only": ["ftx"]}, {"text": "034 Stage 1: about 300 whp (280 on stock exhaust), stock compression, FMIC. Their notes say the bumper reinforcement and core support need clearancing for the intercooler and the heat shield for the turbo. Stage 2 adds their head spacer for more boost.", "only": ["o34"]}, {"text": "JDY builds R32 turbo cars for a living; their kits are specified per customer. Ask for the parts list and software plan in writing before you commit, and ask what they assume about the DSG.", "only": ["jdy"]}, "The DSG. The DQ250's clutch packs are the accepted weak point past roughly 400 lb-ft (community figure). Every tier above DTM wants a TCU tune at minimum; FT-470 and FTX want clutch pack upgrades. Plan for it; it's not in any kit.", "Emissions. A turbo kit relocates the cats or removes them, changes the O2 sensor plumbing and adds hardware the factory ECU doesn't expect. HPA's software integrates the emissions controls; even so, this is not a smog-legal modification in most US states. Know your inspection regime."], "confidence": {"level": "medium", "n": 4, "note": "HPA tier contents and numbers from their listings; 034 from their release thread; DSG limits are community figures."}}, "parts": [{"tier": "aftermarket", "name": "Complete turbo kit", "pn": "see options below", "note": "Turbo, manifold, downpipe, plumbing, injectors, FPR, lines, software, boost controller", "price": "$6,000–14,000", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: head gasket set, head bolts, timing tools (spacer kits)", "pn": "—", "note": "HPA includes the spacer, not the gasket set or bolts", "price": "$300–500", "links": [], "only": ["dtm", "ft", "ftx", "o34"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: colder plugs (one range), coils if original", "pn": "NGK BKR7EIX or kit spec", "note": "", "price": "$100–300", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: fuel pump (in-tank) for FT-470 and above", "pn": "per kit maker", "note": "", "price": "$300–600", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: DSG TCU tune; clutch packs for FT-470/FTX", "pn": "HPA / others", "note": "", "price": "$800–4,000", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: gauges (boost, oil pressure, AFR), oil and coolant, exhaust from the downpipe back", "pn": "—", "note": "Your cat-back must meet the kit's downpipe flange", "price": "$500–2,000", "links": []}, {"tier": "oe", "name": "NOT IN THE BOX: every gasket, o-ring and TTY bolt you disturb; new manifold studs", "pn": "—", "note": "", "price": "$200", "links": []}], "aftermarket": [{"name": "HPA Motorsports EFR kits (DTM / FT-410 / FT-470 / FTX)", "note": "The most complete systems for this car: cast manifold with factory-position O2 bungs, stainless downpipe with flex, spacer kit, 500 mL injectors, FPR, plumbing, oil/water lines, software, boost controller. Liquid-cooled intake manifold from FT-410 up. DTM about $8,900.", "price": "$8,900–14,000", "signal": "Most complete", "links": [{"store": "HPA VR6 turbo program", "url": "https://www.hpamotorsports.com/collections/vr6-single-turbo-program"}]}, {"name": "034Motorsport Stage 1 / Stage 2", "note": "Stage 1 $5,895 with hardware, software and fuelling; FMIC; ~300 whp. Stage 2 head spacer for more boost. Mk5 R32 and A3 kits differ in intake, intercooler and plumbing.", "price": "$5,900 + Stage 2", "signal": "Value complete kit", "links": []}, {"name": "JDY Performance", "note": "R32 specialist; turbo programs built to order. Get the spec in writing.", "price": "by quote", "signal": "Specialist build", "links": []}, {"name": "VF Engineering supercharger (alternative)", "note": "The non-turbo route: centrifugal supercharger kit, around 100 hp over stock, stock compression, simpler install. Different character; instant response, no spacer.", "price": "$6,000–7,000", "signal": "Supercharger alternative", "links": []}], "tools": [{"name": "Everything in the PCV and coolant pipe guides (nose forward, manifold off), plus: engine support bar or hoist, torque wrenches ¼\" to ½\" with angle gauge"}, {"name": "Head spacer tiers: 24V cam locks and crank pin, head bolt socket, straight edge; a clean bench", "only": ["dtm", "ft", "ftx"]}, {"name": "AN wrenches, hose-clamp pliers, a die grinder for clearancing (034: bumper beam, core support, heat shield)", "only": ["o34"]}, {"name": "VCDS or equivalent for adaptation and logging; a wideband AFR gauge for the first drives"}], "before": ["Compression test and an oil analysis. A tired engine doesn't get better with boost.", "Do the maintenance first: timing chains if noisy, coolant pipe and thermostat housing, PCV/valve cover, DSG and Haldex service, plugs and coils. The kit stresses every one of them.", "Read the kit's parts list against this guide's 'not in the box' list and order all of it before the car comes apart.", "Book the DSG software at the same time as the engine software; you don't want to drive 400 lb-ft through a stock TCU map while you wait."], "steps": [{"n": 1, "title": "Where the power comes from", "blocks": [{"t": "text", "b": "Stock, the 3.2 VR6 is rated 250 hp and 236 lb-ft. Every complete kit sits somewhere on the chart below; the numbers are the makers' claims, at the crank unless marked, and the Mk5 DTM figure is HPA's own correction for this car's stock fuelling."}, {"t": "chart", "title": "Manufacturer-claimed peak horsepower", "unit": "hp", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 250}, {"label": "034 Stage 1", "v": 300, "note": "whp, kit spec (280 on stock exhaust)"}, {"label": "HPA DTM (Mk5)", "v": 340, "note": "7 psi, stock fuelling"}, {"label": "HPA FT-410", "v": 410, "note": "16 psi"}, {"label": "HPA FT-470", "v": 470, "note": "19–22 psi"}, {"label": "HPA FTX (EFR 8374)", "v": 500, "note": "'500+' under 20 psi"}], "source": "HPA and 034 published figures; 034's is wheel horsepower. Not dyno-verified by this guide.", "c": {"level": "medium", "n": 3, "note": "Manufacturer claims, cross-listed by two retailers."}}, {"t": "text", "b": "Torque is what you feel and what the DSG has to survive:"}, {"t": "chart", "title": "Manufacturer-claimed peak torque", "unit": "lb-ft", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 236}, {"label": "HPA DTM", "v": 360}, {"label": "HPA FT-410", "v": 420}, {"label": "HPA FT-470", "v": 500}, {"label": "HPA FTX", "v": 500, "note": "'500+'"}, {"label": "DQ250 DSG comfort zone", "v": 400, "note": "community figure for stock clutch packs"}], "source": "HPA figures; 034 doesn't publish torque; DSG figure is R32-forum consensus.", "c": {"level": "community", "n": 3, "note": "Torque claims from HPA; DSG limit is community experience."}}]}, {"n": 2, "title": "What comes off", "blocks": [{"t": "text", "b": "Nose to service position; airbox and intake; intake manifold (PCV guide, steps 1–3); both exhaust manifolds and the downpipe with the cats (headers guide, steps 1–4); the cat-back's front section if the kit's downpipe flange differs; belly pans; on 034 kits, the bumper beam and core support for the FMIC. Coolant drained (you're into the cooling system for the turbo's water lines and, on HPA FT kits, the chargecooler loop)."}, {"t": "ill", "id": "turbo-kit-hero", "cap": "Schematic of the finished system. Exhaust side on the firewall side of the VR6; intake side toward the radiator."}]}, {"n": 3, "title": "Compression drop (spacer tiers)", "only": ["dtm", "ft", "ftx", "o34"], "caution": true, "blocks": [{"t": "text", "b": "HPA's spacer kits and 034's Stage 2: the head comes off. Timing chains locked at TDC with the 24V tools, head bolts out in sequence, head off, faces cleaned, spacer between two head gaskets per the kit's sheet, head on with new bolts to the factory sequence and angle, chains re-timed and checked with two turns by hand. This is the timing chain guide's discipline applied to a head job; if the chains and guides are old, this is the moment they get replaced too."}, {"t": "warn", "b": "A head off a VR6 in the car, against the firewall, with the chains behind it: this is the hardest single step in this app. Many owners have the spacer done by a shop and bolt the kit on themselves afterward. That's a legitimate plan."}]}, {"n": 4, "title": "Exhaust side: manifold, turbo, downpipe", "blocks": [{"t": "text", "b": "Kit manifold on with new gaskets and studs (its O2 bungs sit where the factory ones did, which is why the DSG keeps behaving). Turbo to the manifold flange. Heat shield per the kit. Downpipe to the turbo, then to your cat-back's front joint (adapt or replace the front section). O2 sensors into the kit's bungs. Wastegate and boost controller plumbing per the kit."}, {"t": "warn", "b": "Manifold studs, again. New ones, anti-seize, and torque in a criss-cross; a leak here is a ticking you'll chase for weeks."}]}, {"n": 5, "title": "Oil and coolant to the turbo", "caution": true, "blocks": [{"t": "text", "b": "Oil feed from the kit's tap (filter housing or gallery) with the supplied stainless line; oil return to the pan or the kit's fitting, gravity-fed and never uphill. Coolant lines per the kit, tee'd into the heater or block circuit as specified. Route every line away from the manifold and secure it; a chafed oil line on a hot turbo is a fire."}, {"t": "warn", "b": "Return line: no kinks, no uphill run, no small bore. A turbo that can't drain oil smokes out its seals in a week."}]}, {"n": 6, "title": "Intake side: intercooling, manifold, plumbing", "blocks": [{"t": "text", "b": "HPA FT/FTX: the liquid-cooled cast intake manifold replaces the factory manifold; its water core needs a coolant loop with a front heat exchanger and a pump, routed and bled like a second cooling system. DTM: charge plumbing to the factory manifold per the kit.", "only": ["dtm", "ft", "ftx"]}, {"t": "text", "b": "034: front-mount intercooler behind the clearanced bumper beam, charge pipes to the factory manifold; check the FMIC's clearance to the core support before final assembly.", "only": ["o34"]}, {"t": "text", "b": "Injectors (500 mL on HPA kits) into the rail with new o-rings; FPR per the kit; MAF/intake per the kit's inlet. Every silicone joint clamped relaxed first, tight second."}]}, {"n": 7, "title": "Software, then the first start", "caution": true, "blocks": [{"t": "text", "b": "Load the kit's engine software (and the DSG software you booked). New colder plugs. Oil and coolant filled and bled. Crank with coils unplugged to build oil pressure and fill the turbo's line, then start. Idle, watch for leaks at every oil and coolant joint and every exhaust flange. Let it reach temperature; check the chargecooler loop for air if fitted."}, {"t": "warn", "b": "First drives with a wideband AFR gauge and boost gauge in view, at the kit's lowest boost setting. Lean under boost is how VR6s die. Log, don't guess."}]}, {"n": 8, "title": "Break-in and re-check", "blocks": [{"t": "text", "b": "500 gentle miles, then re-torque manifold and downpipe hardware, re-check every clamp and line, change the oil (spacer tiers: the head gasket set's first heat cycles put debris in it). Only then raise boost per the kit's stages."}]}], "alsoReplace": [{"name": "Timing chains and guides", "why": "If the head is coming off for a spacer, the chains are right there. Don't put a turbo on a rattling VR6."}, {"name": "Coolant pipe, thermostat housing, PCV/valve cover", "why": "All under the manifold you're removing anyway."}, {"name": "Clutch packs / TCU software", "why": "FT-470 and FTX: the DSG is the weak link. Budget it as part of the kit."}, {"name": "Brakes and tyres", "why": "Doubling the power on 345 mm brakes and all-seasons is a decision too. R32 brake guides cover pads and rotors; tyres are on you."}, {"name": "Engine and transmission mounts", "why": "Torque doubles; soft mounts let the manifold and downpipe move against everything."}], "check": {"tab": "Which tier?", "title": "Which tier is right for your car?", "illId": "turbo-kit-hero", "illCap": "Power, budget, and how much of the car you're willing to open up.", "rows": [{"see": "Daily driver, want it noticeably faster, no head work", "means": "Low boost, stock-ish compression.", "do": "034 Stage 1 (no spacer) or HPA DTM (spacer included; more complete)."}, {"see": "Want 400+ and will do the head", "means": "Spacer tier with fuelling.", "do": "HPA FT-410; plan the DSG tune."}, {"see": "Want 500 and know what that means for the DSG", "means": "Top tier, clutch packs, full fuel system.", "do": "HPA FTX or a JDY build; budget the transmission."}, {"see": "Want more power with the least disassembly", "means": "Supercharger.", "do": "VF Engineering; a different guide when we write it."}], "c": {"level": "community", "n": 3, "note": "Community consensus plus manufacturer tiering."}}, "aftercare": ["Oil at 500 miles, then every 5k with a turbo-rated oil.", "Log AFR and boost for the first month; a drift is a leak.", "Re-torque exhaust hardware after the first heat cycles.", "Watch coolant level daily for two weeks: the chargecooler loop and the turbo lines are new places to leak."], "disagreements": [{"topic": "Spacer or not?", "pos": "034 Stage 1 runs stock compression; HPA includes a spacer in every tier.", "call": "Low boost can live at stock compression; anything you'll want more from later wants the spacer, and doing it once is cheaper than twice."}, {"topic": "DSG limit", "pos": "Figures from 350 to 450 lb-ft on the forums.", "call": "Treat 400 as the line and tune the TCU at any tier above DTM."}, {"topic": "Home install?", "pos": "Vendors say 'for your technician'.", "call": "5 out of 5. The bolt-on parts are within reach of someone who's done the manifold-off jobs in this app; the spacer is where most owners bring in a shop."}], "sources": ["HPA Motorsports EFR single-turbo program (tiers, contents, Mk5 fuelling note) via UroTuning and GMP listings", "Audizine: 034Motorsport 3.2 24V VR6 Stage 1 turbo kit release thread (price, whp, clearancing, Stage 2 spacer)", "VWVortex R32 forced-induction and DSG threads (clutch pack limits)", "Motorsport Calibrations R32 turbo build guide (context for big-turbo territory)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
